import {initial,validate} from './model.js?v=pwa-2';
const DB_NAME='project-1000-simple';
function open(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('当前浏览器无法使用本地数据库，请使用 Safari、Chrome 或 Edge。'));return}const r=indexedDB.open(DB_NAME,1);let done=false;const timer=setTimeout(()=>{if(!done){done=true;reject(Error('数据库打开超时。请关闭其他标签页后重试。'))}},5000);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('state'))r.result.createObjectStore('state')};r.onsuccess=()=>{clearTimeout(timer);if(done){r.result.close();return}done=true;resolve(r.result)};r.onerror=()=>{clearTimeout(timer);done=true;reject(r.error)};r.onblocked=()=>{clearTimeout(timer);done=true;reject(Error('数据库被其他页面占用，请关闭其他标签页重试。'))}})}
export async function read(){const db=await open();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite'),store=tx.objectStore('state'),get=store.get('main');let data;get.onsuccess=()=>{try{data=get.result?validate(get.result):initial();if(!get.result)store.put(data,'main')}catch(e){reject(e);tx.abort()}};tx.oncomplete=()=>resolve(data);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('数据库读取失败'))})}finally{db.close()}}
export async function write(data,expectedRevision){const checked=validate(data);const db=await open();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite'),store=tx.objectStore('state'),get=store.get('main');let next,conflict=false;get.onsuccess=()=>{if((get.result?.revision??0)!==expectedRevision){conflict=true;tx.abort();return}next={...checked,revision:expectedRevision+1};store.put(next,'main')};tx.oncomplete=()=>resolve(next);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(Error(conflict?'记录已在另一个标签页更新。请刷新页面再操作。':'保存失败，请检查设备空间或浏览器存储设置。'))})}finally{db.close()}}
